using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns strings from a language pack in the current localization target by their keys. Can be called before authorization
    /// </summary>
    public Task<TdLib.TdApi.Objects.LanguagePackStrings> GetLanguagePackStringsAsync(string languagePackId = default, string[] keys = default)
    {

           using var activity =  StartCallActivity("GetLanguagePackStringsAsync", typeof(GetLanguagePackStrings).FullName ?? "GetLanguagePackStringsAsync");

           try
           {
             return client.GetLanguagePackStringsAsync(languagePackId, keys);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
